import React, { useState, useEffect, useContext } from 'react';
import { useNavigate } from 'react-router-dom';
import api from '../api/client';
import { AuthContext } from '../store/AuthContext';

const StudentHome = () => {
  const { user, logout } = useContext(AuthContext);
  const navigate = useNavigate();
  
  const [status, setStatus] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  // Получаем статус с бэкенда
  useEffect(() => {
    const fetchStatus = async () => {
      try {
        const res = await api.get('/students/me/status/');
        setStatus(res.data);
      } catch (err) {
        setError('Не удалось загрузить данные');
      } finally {
        setLoading(false);
      }
    };
    fetchStatus();
  }, []);

  const handleLogout = () => {
    logout();
    navigate('/');
  };

  if (loading) return <div className="min-h-screen bg-secondary flex items-center justify-center">Загрузка...</div>;
  if (error) return <div className="min-h-screen bg-secondary flex items-center justify-center text-red-500">{error}</div>;

  const isIssued = status?.status_today === 'issued';
  
  // Берем имя (убираем фамилию, оставляем только имя)
  const firstName = status?.full_name ? status.full_name.split(' ')[1] : 'Студент';

  // Генерируем ближайшие 5 дней для календаря
  const days = ['Вс', 'Пн', 'Вт', 'Ср', 'Чт', 'Пт', 'Сб'];
  const today = new Date();
  const nextDays = Array.from({ length: 5 }, (_, i) => {
    const d = new Date(today);
    d.setDate(today.getDate() + i);
    return {
      num: d.getDate(),
      dayName: days[d.getDay()],
      isToday: i === 0
    };
  });

  const monthName = today.toLocaleString('ru-RU', { month: 'long', year: 'numeric' });
  const capitalizedMonth = monthName.charAt(0).toUpperCase() + monthName.slice(1);

  return (
    <div className="min-h-screen w-full bg-primary flex flex-col px-5">
      <div className="mx-auto flex w-full max-w-[480px] flex-1 flex-col pb-10">
        
        {/* Шапка */}
        <header className="flex justify-between items-center pt-12 pb-6">
          <div className="flex items-center gap-2">
            {/* Логотип Талон (стрелочка) */}
            <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
              <path d="M4 12L20 4V10L10 14L20 20V12" stroke="#0D0C0C" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
            </svg>
            <span className="font-semibold text-lg">Талон</span>
          </div>
          <button onClick={handleLogout} className="text-xl font-bold tracking-widest text-black hover:text-gray">
            ...
          </button>
        </header>

        {/* Блик */}
        <div
          aria-hidden
          className="pointer-events-none mx-auto mt-2 h-[140px] w-[220px] rotate-[-20deg]"
          style={{
            background: 'radial-gradient(ellipse closest-side at center, #FF6600 0%, #FFCC00 36%, #FF0055 75%, rgba(255, 0, 85, 0) 100%)',
            filter: 'blur(10px)'
          }}
        />

        {/* Приветствие */}
        <h1 className="mt-8 text-4xl leading-[105%] font-semibold text-black">
          Привет, {firstName}
        </h1>
        <div className="mt-3">
          <span className="bg-black text-primary px-3 py-1.5 rounded-md text-sm font-medium">
            Группа {status?.group}
          </span>
        </div>

        {/* Календарь (визуальный) */}
        <div className="mt-10 flex justify-between items-center">
          <h2 className="text-xl font-semibold">{capitalizedMonth}</h2>
          <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
            <rect x="3" y="4" width="18" height="18" rx="2" ry="2"></rect>
            <line x1="16" y1="2" x2="16" y2="6"></line>
            <line x1="8" y1="2" x2="8" y2="6"></line>
            <line x1="3" y1="10" x2="21" y2="10"></line>
          </svg>
        </div>

        {/* Дни */}
        <div className="mt-4 flex justify-between">
          {nextDays.map((d, i) => (
            <div key={i} className={`flex flex-col items-center justify-center w-12 h-16 rounded-xl ${d.isToday ? 'bg-black text-primary' : 'text-gray'}`}>
              <span className="text-lg font-semibold">{d.num}</span>
              <span className="text-xs">{d.dayName}</span>
            </div>
          ))}
        </div>

        {/* Умная плашка (Зеленая / Красная) */}
        <div className={`mt-8 rounded-[24px] p-6 flex flex-col justify-center transition-colors duration-300 ${
          isIssued ? 'bg-[#FF0000]' : 'bg-[#88FF00]' // Красный или Зеленый
        }`}>
          <h3 className="text-2xl font-bold text-black leading-tight">
            {isIssued ? 'Вы уже забрали свою еду' : 'Можно забрать еду!'}
          </h3>
        </div>

        {/* Текст описания */}
        <p className="mt-4 text-sm leading-[140%] text-gray px-2">
          {isIssued 
            ? 'В день вы можете получить только одну порцию еды, следующая будет доступна на следующий день'
            : 'Спускайся быстрее в столовую, забирай свою еду и кушай на здоровье'}
        </p>

        {/* Кнопка */}
        <div className="mt-auto pt-8">
          <button
            type="button"
            disabled={isIssued}
            onClick={() => navigate('/student/scan')}
            className={`h-14 w-full rounded-2xl flex items-center justify-center gap-3 text-base font-medium transition-colors
              ${isIssued 
                ? 'bg-gray/30 text-gray cursor-not-allowed' 
                : 'bg-black text-primary hover:bg-gray-900'}`}
          >
            {/* Иконка сканера */}
            <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
              <path d="M3 7V5a2 2 0 0 1 2-2h2"></path>
              <path d="M17 3h2a2 2 0 0 1 2 2v2"></path>
              <path d="M21 17v2a2 2 0 0 1-2 2h-2"></path>
              <path d="M7 21H5a2 2 0 0 1-2-2v-2"></path>
              <rect x="7" y="7" width="10" height="10" rx="1"></rect>
            </svg>
            Отсканировать QR-код
          </button>
        </div>

      </div>
    </div>
  );
};

export default StudentHome;
